import { describe, it, expect } from "vitest";
import { ipaymuProvider } from "./ipaymu";

describe("iPaymu Webhook & Signature Verification Simulation", () => {
  it("verifies callback signature correctly when signature header is present", () => {
    if (!ipaymuProvider.isConfigured()) return;

    const payload = JSON.stringify({
      trx_id: "12345678",
      status: "berhasil",
      reference_id: "KK-20261018-9999",
      amount: 150000,
      via: "QRIS",
    });

    // Signature generated by iPaymu using API Key
    const validSignature = ipaymuProvider.generateSignature("POST", payload);
    const isValid = ipaymuProvider.verifyCallbackSignature(payload, validSignature);
    expect(isValid).toBe(true);

    const isInvalid = ipaymuProvider.verifyCallbackSignature(payload, "invalid_sig_123");
    expect(isInvalid).toBe(false);
  });

  it("handles empty or missing signature with appropriate fallback", () => {
    const isValid = ipaymuProvider.verifyCallbackSignature("test", "");
    expect(isValid).toBe(false);
  });
});
